using System;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEngine.SceneManagement;using Codice.Mechanics;using Codice.Characters;using Codice.UI;using Codice.Enemies;using TMPro;
public static class VerifyAuthoring{
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 public static async Task<string> Run(){
  var menu=UnityEngine.Object.FindAnyObjectByType<MainMenuUI>();Check(menu,"Menu absent");await Task.Delay(500);Check(menu.transform.Find("MENU EDITABLE")&&!menu.transform.Find("MENU EDITABLE").gameObject.activeSelf,"Authored duplicate visible");Check(menu.transform.Find("Main menu canvas").GetComponentsInChildren<TMPro.TextMeshProUGUI>().Any(x=>x.text=="CINDERS SOULS"),"Runtime menu invisible");
  var state=new CharacterState();state.Initialize(PlayerClass.Mage);Check(MainMenuUI.UnlockCheats("Good!"),"Good command rejected");float hp=state.Health,armor=state.Armor;state.Damage(999999,true);Check(state.Health==hp&&state.Armor==armor,"God received damage");for(int i=0;i<20;i++)Check(state.SpendMana(40),"Mana exhausted");Check(state.Mana==state.MaxMana,"Mana not full");Check(MainMenuUI.UnlockCheats("Macpato"),"Money command rejected");for(int i=0;i<10;i++)Check(state.SpendGold(1000000),"Gold exhausted");Check(state.Gold==int.MaxValue,"Infinite money missing");Check(MainMenuUI.UnlockCheats("Macpato")&&!SessionCheats.Rich,"Money cannot disable");Check(!state.SpendGold(1),"Money bypass remained enabled");
  SceneManager.LoadScene("SalaPruebas");for(int i=0;i<150&&(!RunDirector.Instance||!RunDirector.Instance.Player);i++)await Task.Delay(100);await Task.Delay(600);var lab=UnityEngine.Object.FindAnyObjectByType<CombatTestRoom>();Check(lab&&lab.enemyPrefabs.Length>0,"Missing test prefabs");Check(UnityEngine.Object.FindObjectsByType<BasicEnemy>().Length==0,"Automatic encounter in test room");Check(lab.SpawnSelected(),"Lab spawn failed");await Task.Delay(150);var p=RunDirector.Instance.Player;var enemy=UnityEngine.Object.FindAnyObjectByType<BasicEnemy>();var boss=UnityEngine.Object.FindAnyObjectByType<Codice.Bosses.BossCharacter>();if(enemy){enemy.SetPaused(false);enemy.ReceiveDamage(new DamageInfo{amount=1,source=p.gameObject});Check(!enemy.IsAlive,"God damage did not kill");}else{Check(boss,"Missing spawned actor");boss.SetPaused(false);boss.ReceiveDamage(new DamageInfo{amount=1,source=p.gameObject});Check(!boss.IsAlive,"God damage did not kill boss");}lab.ClearEnemies();SessionCheats.Execute("Good!");Check(!SessionCheats.God,"God cannot disable");Debug.Log("[AuthoringTest] PASS editable menu/runtime, toggled god/mana/lethal damage/money, isolated lab spawn");return "PASS menu, cheats and test room";
 }
}
